@@ -217,7 +217,7 @@ get_packages_to_install() {

 install_packages() {
 	# evaluates the package manager
-	PKG_MANAGER_PATH=$({ command -v apk || command -v apt || command -v dnf || command -v rpm-ostree || command -v yum || command -v zypper || command -v pacman; })
+	PKG_MANAGER_PATH=$({ command -v apk || command -v apt || command -v dnf || command -v rpm-ostree || command -v yum || command -v zypper || command -v pacman || command -v eopkg-cli; })

